import { useState } from 'react'
import {
  Bell, Sun, Moon, AlignCenterHorizontal, LogOut, User, Mail, Lock, LoaderCircle,
  ShieldCheck,
} from 'lucide-react'
import { useAuth, type AuthUser } from '../lib/auth'
import { useStore } from '../lib/store'
import { Button } from '../components/ui'
import AuthNight from '../components/AuthNight'
import { cx } from '../lib/utils'
import type { ReaderWidth } from '../types'
import posthog, { isPostHogEnabled } from '../lib/posthog'

/**
 * Account page: sign in / create an account when logged out; profile,
 * preferences, and sign-out when logged in. Each account's library, reading
 * progress, and ratings are private to it and sync across devices.
 */
export default function Account() {
  const { user, initializing, login, register, logout } = useAuth()

  if (initializing) {
    return (
      <main className="mx-auto grid min-h-[60vh] max-w-[900px] place-items-center px-4">
        <LoaderCircle className="animate-spin text-ink-faint" />
      </main>
    )
  }

  return user ? <SignedIn username={user.username} email={user.email} onLogout={logout} /> : <AuthForm onLogin={login} onRegister={register} />
}

function SignedIn({ username, email, onLogout }: { username: string; email: string; onLogout: () => Promise<void> }) {
  const { prefs, setAtmosphere, setWidth, setNotifyOnDrop, library, progress, ratings, toast } =
    useStore()

  return (
    <main className="mx-auto max-w-[900px] animate-fade-up px-4 py-10 sm:px-6 lg:px-8">
      <div className="overflow-hidden rounded-[20px] border border-line bg-paper">
        {/* Profile card */}
        <div className="bg-[#181817] px-6 py-10 text-white sm:px-8">
          <div className="flex flex-wrap items-center gap-5">
            <div className="grid h-16 w-16 place-items-center rounded-full bg-accent text-xl font-black uppercase text-white">
              {username.slice(0, 1)}
            </div>
            <div className="min-w-0">
              <div className="eyebrow text-accent">Reader Account</div>
              <h1 className="mt-1 break-words text-2xl font-extrabold tracking-tight">{username}</h1>
              <p className="mt-1 truncate text-sm text-white/60">{email}</p>
            </div>
            <div className="flex-1" />
            <div className="flex gap-3 text-center text-white/70">
              <div className="rounded-[12px] bg-white/10 px-4 py-3 backdrop-blur">
                <div className="text-xl font-extrabold text-white">{library.length}</div>
                <div className="text-[11px] uppercase tracking-wide">Saved</div>
              </div>
              <div className="rounded-[12px] bg-white/10 px-4 py-3 backdrop-blur">
                <div className="text-xl font-extrabold text-white">{Object.keys(progress).length}</div>
                <div className="text-[11px] uppercase tracking-wide">In Progress</div>
              </div>
              <div className="rounded-[12px] bg-white/10 px-4 py-3 backdrop-blur">
                <div className="text-xl font-extrabold text-white">{Object.keys(ratings).length}</div>
                <div className="text-[11px] uppercase tracking-wide">Rated</div>
              </div>
            </div>
          </div>
          <p className="mt-4 inline-flex items-center gap-1.5 text-xs text-white/50">
            <ShieldCheck width={13} height={13} className="text-accent" />
            Your library, reading progress, and ratings are private to your account and sync
            automatically across devices.
          </p>
        </div>

        <div className="p-6 sm:p-8">
          {/* Preferences */}
          <section>
            <h2 className="text-lg font-extrabold tracking-tight">Reader Preferences</h2>

            <div className="mt-5">
              <div className="eyebrow mb-3 text-ink-faint">Reader Color Atmosphere</div>
              <div className="grid gap-3 sm:grid-cols-2">
                <PrefTile
                  active={prefs.atmosphere === 'light'}
                  onClick={() => setAtmosphere('light')}
                  icon={<Sun />}
                  title="Editorial Light"
                  desc="Warm paper canvas, default atmosphere"
                />
                <PrefTile
                  active={prefs.atmosphere === 'dark'}
                  onClick={() => setAtmosphere('dark')}
                  icon={<Moon />}
                  title="Onyx Dark"
                  desc="Deep ink canvas for night reading"
                />
              </div>
            </div>

            <div className="mt-7">
              <div className="eyebrow mb-3 text-ink-faint">Default Reader Width</div>
              <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
                {WIDTHS.map((w) => (
                  <button
                    key={w.key}
                    onClick={() => setWidth(w.key)}
                    className={cx(
                      'rounded-[14px] border p-4 text-left transition-all',
                      prefs.width === w.key
                        ? 'border-accent bg-accent/5 shadow-sm'
                        : 'border-line-strong bg-paper hover:border-ink',
                    )}
                  >
                    <AlignCenterHorizontal
                      width={16}
                      height={16}
                      className={prefs.width === w.key ? 'text-accent' : 'text-ink-faint'}
                    />
                    <div className="mt-2.5 text-sm font-bold">{w.label}</div>
                    <div className="text-xs text-ink-faint">{w.desc}</div>
                  </button>
                ))}
              </div>
            </div>

            <div className="mt-7">
              <div className="eyebrow mb-3 text-ink-faint">Notifications</div>
              <button
                onClick={() => {
                  const enabled = !prefs.notifyOnDrop
                  setNotifyOnDrop(enabled)
                  if (isPostHogEnabled) {
                    posthog.capture('release_alert_preference_changed', { enabled })
                  }
                  toast(
                    !prefs.notifyOnDrop
                      ? 'New Chapter Release Alerts enabled'
                      : 'New Chapter Release Alerts disabled',
                  )
                }}
                className="flex w-full items-center justify-between rounded-[14px] border border-line bg-paper-2/50 p-4 text-left transition-colors hover:border-ink"
              >
                <div className="flex items-start gap-3">
                  <Bell
                    width={18}
                    height={18}
                    className={prefs.notifyOnDrop ? 'text-accent' : 'text-ink-faint'}
                  />
                  <div>
                    <div className="text-sm font-bold">New Chapter Release Alerts</div>
                    <div className="text-xs text-ink-faint">
                      Notify when bookmarked series drop new weekly chapters
                    </div>
                  </div>
                </div>
                <span
                  className={cx(
                    'relative h-6 w-11 shrink-0 rounded-full transition-colors',
                    prefs.notifyOnDrop ? 'bg-accent' : 'bg-line-strong',
                  )}
                >
                  <span
                    className={cx(
                      'absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition-all',
                      prefs.notifyOnDrop ? 'left-[22px]' : 'left-0.5',
                    )}
                  />
                </span>
              </button>
            </div>
          </section>

          {/* Account actions */}
          <section className="mt-8 flex flex-wrap items-center justify-between gap-3 border-t border-line pt-6">
            <div className="flex min-w-0 items-center gap-2 text-sm text-ink-faint">
              <User width={15} height={15} className="shrink-0" />
              <span className="truncate">{email}</span>
            </div>
            <button
              onClick={async () => {
                await onLogout()
                toast('Signed out — reading data stays saved to this device until you sign in again')
              }}
              className="inline-flex items-center gap-2 text-sm font-semibold text-ink-soft transition-colors hover:text-accent"
            >
              <LogOut width={15} height={15} /> Sign Out
            </button>
          </section>
        </div>
      </div>
    </main>
  )
}

const WIDTHS: { key: ReaderWidth; label: string; desc: string }[] = [
  { key: 'narrow', label: 'Narrow', desc: 'Focused column' },
  { key: 'standard', label: 'Standard', desc: 'Balanced canvas' },
  { key: 'wide', label: 'Wide', desc: 'Cinematic spread' },
  { key: 'full', label: 'Full', desc: 'Edge to edge' },
]

function AuthForm({
  onLogin,
  onRegister,
}: {
  onLogin: (identifier: string, password: string) => Promise<AuthUser | string>
  onRegister: (username: string, email: string, password: string) => Promise<AuthUser | string>
}) {
  const { toast } = useStore()
  const [mode, setMode] = useState<'login' | 'register'>('login')
  const [identifier, setIdentifier] = useState('')
  const [username, setUsername] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    if (mode === 'register' && password !== confirm) {
      setError('Passwords do not match')
      return
    }
    setBusy(true)
    const result =
      mode === 'login'
        ? await onLogin(identifier.trim(), password)
        : await onRegister(username.trim(), email.trim(), password)
    setBusy(false)
    if (typeof result === 'string') {
      setError(result)
    } else {
      toast(
        mode === 'login'
          ? `Welcome back, ${result.username}!`
          : `Account created — welcome, ${result.username}!`,
        'accent',
      )
    }
  }

  return (
    <main className="relative min-h-screen">
      {/* animated night backdrop — GPU-composited CSS scene, pauses when the
          tab is hidden and for prefers-reduced-motion users */}
      <AuthNight />

      <div className="relative z-10 mx-auto grid min-h-screen max-w-[460px] animate-fade-up place-items-center px-4 py-14">
        <div className="w-full">
          {/* glass card */}
          <div className="relative overflow-hidden rounded-[20px] border border-[#241f1c]/10 bg-[#fffdf7]/82 shadow-[0_30px_80px_-24px_rgba(36,31,28,0.4)] backdrop-blur-xl">
            {/* gradient hairline on the card's top edge */}
            <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-accent to-transparent" />

            <div className="px-7 py-9 sm:px-9">
              <div className="text-center">
                {/* kamon emblem */}
                <img
                  src="/auth-emblem.png"
                  alt="MANHWAS emblem"
                  width={84}
                  height={84}
                  className="mx-auto h-[84px] w-[84px] rounded-full object-cover ring-2 ring-accent/70 ring-offset-2 ring-offset-[#fffdf7] shadow-[0_6px_24px_rgba(36,31,28,0.28)]"
                />
                <h1 className="mt-4 text-[26px] font-extrabold tracking-tight text-[#241f1c]">
                  {mode === 'login' ? 'Welcome Back' : 'Begin Your Journey'}
                </h1>
                <p className="mt-1.5 text-sm">
                  <span className="font-semibold text-accent">
                    {mode === 'login' ? 'おかえり' : 'ようこそ'}
                  </span>
                  <span className="text-[#241f1c]/55">
                    {mode === 'login'
                      ? ' · Continue your journey'
                      : ' · Your journey begins — it\u2019s free'}
                  </span>
                </p>
              </div>

              <form onSubmit={submit} className="mt-8 space-y-4">
                {mode === 'register' ? (
                  <>
                    <AuthField
                      icon={<User width={15} height={15} />}
                      label="Username"
                      type="text"
                      placeholder="your_username"
                      value={username}
                      onChange={setUsername}
                      autoComplete="username"
                      required
                    />
                    <AuthField
                      icon={<Mail width={15} height={15} />}
                      label="Email"
                      type="email"
                      placeholder="you@example.com"
                      value={email}
                      onChange={setEmail}
                      autoComplete="email"
                      required
                    />
                  </>
                ) : (
                  <AuthField
                    icon={<User width={15} height={15} />}
                    label="Username"
                    type="text"
                    placeholder="your_username"
                    value={identifier}
                    onChange={setIdentifier}
                    autoComplete="username"
                    required
                  />
                )}
                <AuthField
                  icon={<Lock width={15} height={15} />}
                  label="Password"
                  type="password"
                  placeholder="••••••••"
                  value={password}
                  onChange={setPassword}
                  autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
                  required
                />
                {mode === 'register' && (
                  <AuthField
                    icon={<Lock width={15} height={15} />}
                    label="Confirm password"
                    type="password"
                    placeholder="••••••••"
                    value={confirm}
                    onChange={setConfirm}
                    autoComplete="new-password"
                    required
                  />
                )}

                {error && (
                  <p className="rounded-[10px] border border-red-300/60 bg-red-50 px-3.5 py-2.5 text-sm text-red-700">
                    {error}
                  </p>
                )}

                <button
                  type="submit"
                  disabled={busy}
                  className={cx(
                    'flex h-12 w-full items-center justify-center gap-2 rounded-[12px] text-base font-bold text-white shadow-lg transition-all hover:brightness-110 active:scale-[0.99]',
                    // color psychology: returning users get the calm night-violet
                    // (trust, belonging); new users get the warm coral (action,
                    // energy) — the eye is drawn to the sign-up CTA
                    mode === 'login'
                      ? 'bg-[#241f1c] hover:bg-[#3a332e]'
                      : 'bg-gradient-to-r from-accent to-[#f08a5f]',
                    busy && 'cursor-wait opacity-70',
                  )}
                >
                  {busy ? (
                    <LoaderCircle width={17} height={17} className="animate-spin" />
                  ) : mode === 'login' ? (
                    'Sign In'
                  ) : (
                    'Start Reading — It\u2019s Free'
                  )}
                </button>
              </form>

              <p className="mt-6 text-center text-sm text-[#241f1c]/55">
                {mode === 'login' ? "New here? " : 'Already have an account? '}
                <button
                  type="button"
                  onClick={() => {
                    setMode(mode === 'login' ? 'register' : 'login')
                    setError('')
                  }}
                  className="font-semibold text-accent hover:underline"
                >
                  {mode === 'login' ? 'Create an account' : 'Sign in'}
                </button>
              </p>
            </div>
          </div>

          <p className={cx('mt-6 text-center text-xs', 'text-[#241f1c]/40')}>
            Your library and progress stay private — sync across your devices.
          </p>
        </div>
      </div>
    </main>
  )
}

function AuthField({
  icon,
  label,
  type,
  placeholder,
  value,
  onChange,
  autoComplete,
  required,
}: {
  icon: React.ReactNode
  label: string
  type: string
  placeholder: string
  value: string
  onChange: (v: string) => void
  autoComplete?: string
  required?: boolean
}) {
  return (
    <label className="block">
      <span className="mb-1.5 block text-[11px] font-bold uppercase tracking-[0.14em] text-[#241f1c]/50">
        {label}
      </span>
      <div className="flex h-12 items-center gap-2.5 rounded-[12px] border border-[#241f1c]/14 bg-white/75 px-3.5 transition-colors focus-within:border-accent">
        <span className="shrink-0 text-ink-faint">{icon}</span>
        <input
          type={type}
          placeholder={placeholder}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          autoComplete={autoComplete}
          required={required}
          className="w-full bg-transparent text-sm text-[#241f1c] outline-none placeholder:text-[#241f1c]/35"
        />
      </div>
    </label>
  )
}

function PrefTile({
  active,
  onClick,
  icon,
  title,
  desc,
}: {
  active: boolean
  onClick: () => void
  icon: React.ReactNode
  title: string
  desc: string
}) {
  return (
    <button
      onClick={onClick}
      className={cx(
        'flex items-start gap-4 rounded-[14px] border p-5 text-left transition-all',
        active ? 'border-accent bg-accent/5 shadow-sm' : 'border-line-strong bg-paper hover:border-ink',
      )}
    >
      <span className={cx('mt-0.5', active ? 'text-accent' : 'text-ink-faint')}>{icon}</span>
      <span>
        <span className="block text-sm font-bold">{title}</span>
        <span className="mt-0.5 block text-xs text-ink-faint">{desc}</span>
      </span>
    </button>
  )
}
