import { useEffect, useState } from 'react'

/**
 * Animated dawn backdrop for the sign-in / sign-up screen — OUR brand look:
 * warm paper-dawn sky, a coral sun, ink-wash ridges, manga screentone
 * halftone dots, drifting sakura petals in the site's coral.
 *
 * Pure CSS/SVG — no video, no canvas, no JS animation loop. Every moving
 * piece animates transform/opacity only (GPU-composited, no layout or
 * paint work), so it stays smooth on low-end Androids and costs ~0 CPU
 * when idle. The whole scene pauses when the tab is hidden and disables
 * itself for prefers-reduced-motion users.
 *
 * Deterministic pseudo-random layout (seeded, no re-render flicker).
 */
function seeded(seed: number) {
  let s = seed
  return () => {
    s = (s * 9301 + 49297) % 233280
    return s / 233280
  }
}

const rand = seeded(777)

const STARS = Array.from({ length: 12 }, (_, i) => ({
  x: +(rand() * 100).toFixed(2),
  y: +(rand() * 55).toFixed(2),
  size: +(2 + rand() * 2.5).toFixed(2),
  delay: +(rand() * 7).toFixed(2),
  dur: +(4 + rand() * 5).toFixed(2),
  key: `s${i}`,
}))

const PETALS = Array.from({ length: 10 }, (_, i) => ({
  x: +(3 + rand() * 94).toFixed(2),
  delay: +(rand() * 18).toFixed(2),
  dur: +(14 + rand() * 10).toFixed(2),
  scale: +(0.7 + rand() * 0.6).toFixed(2),
  drift: +(rand() * 70 - 35).toFixed(0),
  key: `p${i}`,
}))

export default function AuthNight() {
  const [paused, setPaused] = useState(false)

  // save battery: freeze the scene while the tab is hidden
  useEffect(() => {
    const onVis = () => setPaused(document.hidden)
    document.addEventListener('visibilitychange', onVis)
    return () => document.removeEventListener('visibilitychange', onVis)
  }, [])

  return (
    <div
      className={`auth-night pointer-events-none fixed inset-0 z-0 overflow-hidden ${paused ? 'auth-night-paused' : ''}`}
      aria-hidden
    >
      {/* warm paper-dawn sky */}
      <div className="absolute inset-0 auth-sky" />

      {/* manga screentone halftone dots (subtle, top corner) */}
      <div className="auth-halftone" />

      {/* drifting light motes */}
      {STARS.map((s) => (
        <span
          key={s.key}
          className="auth-star"
          style={{
            left: `${s.x}%`,
            top: `${s.y}%`,
            width: s.size,
            height: s.size,
            animationDelay: `${s.delay}s`,
            animationDuration: `${s.dur}s`,
          }}
        />
      ))}

      {/* coral sun + haze */}
      <div className="auth-sun-haze" />
      <div className="auth-sun" />

      {/* ink-wash ridges (three layers, static) */}
      <svg className="auth-mountains" viewBox="0 0 1440 320" preserveAspectRatio="none">
        <path
          className="auth-ridge-back"
          d="M0 210 L140 168 L280 220 L430 150 L580 212 L740 164 L920 228 L1080 158 L1240 218 L1350 182 L1440 212 L1440 320 L0 320 Z"
        />
        <path
          className="auth-ridge-mid"
          d="M0 252 L180 214 L340 262 L520 204 L700 258 L880 216 L1060 266 L1250 220 L1440 258 L1440 320 L0 320 Z"
        />
        <path
          className="auth-ridge-front"
          d="M0 288 L170 252 L330 292 L510 240 L690 288 L870 248 L1050 294 L1240 254 L1440 288 L1440 320 L0 320 Z"
        />
      </svg>

      {/* falling sakura petals in the site coral */}
      {PETALS.map((p) => (
        <span
          key={p.key}
          className="auth-petal"
          style={{
            left: `${p.x}%`,
            animationDelay: `${p.delay}s`,
            animationDuration: `${p.dur}s`,
            ['--petal-scale' as string]: p.scale,
            ['--petal-drift' as string]: `${p.drift}px`,
          }}
        />
      ))}
    </div>
  )
}
